/* One portable product image; only re-encoded JPEG data enters stored documents. */
function productImageHTML(value){try{if(!DomainSchema.productImage(value))return '';}catch{return '';}return '<img alt="Изображение изделия" src="'+value+'" style="display:block;width:320px;max-width:100%;max-height:220px;object-fit:contain;margin:16px 0;break-inside:avoid">';}
function productImageCard(){return `<div class="card"><h2>Изображение изделия</h2><p class="small">Попадёт во внутренний PDF-бланк, клиентский расчёт и КП. Выберите PNG, JPEG или WebP либо вставьте скриншот в поле ниже. Изображение уменьшается для хранения на устройстве.</p>${productImageHTML(state.productImage)}<div class="field"><label for="product-image-file">${state.productImage?'Заменить изображение':'Прикрепить изображение'}</label><input id="product-image-file" type="file" accept="image/png,image/jpeg,image/webp" onchange="attachProductImage(this.files[0]);this.value='' "></div><div tabindex="0" role="textbox" aria-label="Вставить скриншот изделия" onpaste="pasteProductImage(event)" style="border:1px dashed;padding:16px">Нажмите здесь и вставьте скриншот (Ctrl+V)</div>${state.productImage?'<button onclick="delete state.productImage;persist();render()">Удалить изображение</button>':''}</div>`;}
let productImageRequest=0;
function pasteProductImage(event){const file=[...(event.clipboardData?.items||[])].find(x=>x.kind==='file'&&x.type.startsWith('image/'))?.getAsFile();if(file){event.preventDefault();attachProductImage(file);}}
async function attachProductImage(file){if(!file)return;const target=state,request=++productImageRequest;let url;try{if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>15e6)throw Error('Выберите PNG, JPEG или WebP размером до 15 МБ');url=URL.createObjectURL(file);const image=new Image();image.src=url;await image.decode();if(!image.naturalWidth||!image.naturalHeight)throw Error('Не удалось прочитать изображение');const canvas=document.createElement('canvas'),scale=Math.min(1,1200/image.naturalWidth,1200/image.naturalHeight);canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);let data;for(const quality of [.85,.7,.55,.4,.25]){data=canvas.toDataURL('image/jpeg',quality);if(data.length<=180000)break;}DomainSchema.productImage(data);if(state!==target||request!==productImageRequest)return;const previous=state.productImage;state.productImage=data;persist();if(window.draftSaveFailed){if(previous)state.productImage=previous;else delete state.productImage;toast('Недостаточно места. Изображение не добавлено; сохраните JSON.');}else toast('Изображение прикреплено');render();}catch(e){toast(e.message);}finally{if(url)URL.revokeObjectURL(url);}}

const moneyFormat=new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',maximumFractionDigits:2}),tinyMoneyFormat=new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',maximumFractionDigits:8}),decimalFormat=new Intl.NumberFormat('ru-RU',{maximumFractionDigits:3});
const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=x=>Number.isFinite(x)?(Math.abs(x)>0&&Math.abs(x)<0.01?tinyMoneyFormat:moneyFormat).format(x):'—',dec=x=>Number.isFinite(x)?decimalFormat.format(x):'—';
const labels=['Карточка заказа','Материалы','Технология и работы','Параметры цены','Результат'];let page=0,mode='internal',filterKind='material';
const blank=()=>({version:1,draftId:crypto.randomUUID(),schemaVersion:1,engineVersion:'cost-review-v1',name:'Новое изделие',projectName:'',code:'',client:'',type:'МАФ и мебель',qty:1,scope:'Изготовление',notes:'',clientNotes:'',overhead:7,transport:6,markup:40,markupBase:'cost',vat:22,profitTax:25,lines:[],updated:new Date().toISOString()});
let state=blank();try{const saved=JSON.parse(localStorage.getItem('izdelie-state'));if(saved&&validState(saved))state=saved;}catch{}
function validState(s){try{DomainSchema.calculation(s);return true}catch{return false}}
function persist(){state.updated=new Date().toISOString();try{localStorage.setItem('izdelie-state',JSON.stringify(state));window.draftSaveFailed=false;$('saveState').textContent='Сохранено на устройстве';}catch{window.draftSaveFailed=true;$('saveState').textContent='Не удалось сохранить — скачайте JSON';} $('crumb').textContent=state.name;}
function toast(t){$('toast').textContent=t;$('toast').style.opacity=1;setTimeout(()=>$('toast').style.opacity=0,2800)}
function go(n){page=n;render();window.scrollTo({top:0,behavior:'smooth'})}
function set(k,v){state[k]=v;if(k==='scope')state.requiredServices={design:/Проектирование|Комплексный/.test(v),installation:/монтаж|Комплексный/.test(v),delivery:/Комплексный/.test(v)};persist();if(k==='qty'||k==='scope'||page===3)render();else refreshSummary()}
function newProject(){modal('Новый расчёт',`<p class="subtitle">Текущий расчёт хранится на этом устройстве. Скачайте JSON, чтобы сохранить отдельную версию.</p><div class="mini-actions"><button onclick="saveFile()">Скачать текущий</button><button class="primary" onclick="state=blank();persist();page=0;render();$('modal').close()">Создать пустой расчёт</button><button onclick="loadDemo()">Открыть учебный пример</button></div><div class="mini-actions"><button onclick="$('modal').close();go(7)">Открыть базу изделий</button></div><div class="divider"></div><h3>Снимки предыдущей версии</h3><div id="snapshots"></div>`);renderSnapshots()}
function renderSnapshots(){let a=[];try{a=JSON.parse(localStorage.getItem('izdelie-snapshots')||'[]')}catch{}$('snapshots').innerHTML=a.length?a.map((s,i)=>`<div class="metricline"><span>${esc(s.name)} · ${s.qty} шт.</span><button class="iconbtn" onclick="openSnapshot(${i})">Открыть</button></div>`).join(''):'<p class="small">Снимки появятся после сохранения в разделе «Результат».</p>'}
function openSnapshot(i){try{const s=JSON.parse(localStorage.getItem('izdelie-snapshots'))[i];if(!validState(s))throw Error();state=s;persist();page=0;render();$('modal').close()}catch{toast('Снимок недоступен')}}
function snapshot(){try{let a=JSON.parse(localStorage.getItem('izdelie-snapshots')||'[]');a.unshift(structuredClone(state));localStorage.setItem('izdelie-snapshots',JSON.stringify(a.slice(0,30)));toast('Снимок сохранён на этом устройстве')}catch{toast('Не удалось сохранить снимок. Скачайте JSON.')}}
function lineFrom(c){const workshop=c?.workshop||(c?.kind==='work'&&typeof ProductionWorkCore!=='undefined'?ProductionWorkCore.classifyWorkshop(c).workshop:'Сборочный');return {id:crypto.randomUUID(),catalogId:c?.id||'',name:c?.name||'',unit:c?.unit||'шт.',price:c?.price??null,basePrice:c?.basePrice??c?.price??null,pricingMode:'calculated',baseUnit:c?.unit||'шт.',sourceFormula:c?.sourceFormula||'',sourceParameters:c?.sourceParameters??null,sourceFinalCost:c?.sourceFinalCost??c?.price??null,physicalQuantity:null,physicalUnit:c?.productivityUnit||'',productivity:c?.productivity??null,productivityUnit:c?.productivityUnit||'',productivityStatus:c?.productivityStatus||'missing',unitChangeNotice:false,workshop,productionOrder:null,qty:null,reserve:0,pack:c?.sourcePack>0?c.sourcePack:1,scope:'unit',allocation:'whole',group:'Общее изделие',kind:c?.kind||filterKind,confirmed:false,deliveryIncluded:false,date:c?.date||'',source:c?.purchaseSource||(c?`${c.book} · ${c.sheet}!${c.priceCell}`:'Ручной ввод'),mass:c?.mass??null};}
function loadDemo(){state=blank();state.name='Скамья из лиственницы';state.code='УЧЕБНЫЙ ПРИМЕР';state.qty=10;state.notes='Учебная конфигурация для знакомства с интерфейсом. Не полная калькуляция УМ016. Объёмы условные; крепёж, покрытия и остальные операции не включены.';state.clientNotes='Учебный пример: состав изделия неполный, объёмы условные. Крепёж, покрытия и остальные операции не включены.';const c=CATALOG.find(x=>x.id==='Пиломатериалы:37');const l=lineFrom(c);l.qty=9.5;l.pack=1;l.group='Деревянные детали';state.lines.push(l);const w=CATALOG.find(x=>x.kind==='work'&&x.unit==='ч/ч'&&x.price>0);if(w){const a=lineFrom(w);a.qty=2;a.group='Подготовка производства';a.scope='batch';state.lines.push(a)}persist();page=0;render();$('modal').close();toast('Учебный пример. Объёмы требуют проверки')}
function title(eye,h,sub,tag='Предварительный расчёт'){return `<div class="page-title"><div><div class="eyebrow">${eye}</div><h1>${h}</h1><p class="subtitle">${sub}</p></div><span class="tag">${tag}</span></div>`}
function steps(){return `<div class="steps">${labels.map((l,i)=>`<button class="${page===i?'active':''}" onclick="go(${i})"><b>${i+1}</b>${l}</button>`).join('')}</div>`}
function field(label,k,type='text',hint=''){return `<div class="field"><label for="f-${k}">${label}</label><input id="f-${k}" type="${type}" value="${esc(state[k])}" ${type==='number'?'min="0" step="any"':''} onchange="set('${k}',${type==='number'?"this.value===''?null:Number(this.value)":'this.value'})">${hint?`<div class="hint">${hint}</div>`:''}</div>`}
function summary(){const r=CostEngine.calculate(state);return `<div class="summary" id="summary"><div class="eyebrow">${r.partial?'Известная часть цены':'Оценка стоимости'}</div><div class="big">${money(r.unit)}</div><div class="small">за изделие с НДС ${dec(state.vat)}%</div><div class="divider"></div><div class="metricline"><span>Партия</span><b>${dec(state.qty)} шт.</b></div><div class="metricline"><span>Материалы / шт.</span><b>${money(r.M/state.qty)}</b></div><div class="metricline"><span>Производственные работы / шт.</span><b>${money((r.W-r.D)/state.qty)}</b></div><div class="metricline"><span>Проектирование / шт.</span><b>${money(r.D/state.qty)}</b></div><div class="metricline"><span>Себестоимость / шт.</span><b>${money(r.costUnit)}</b></div><div class="divider"></div><div class="metricline"><span>Вся партия с НДС</span><b>${money(r.total)}</b></div><div class="note info">${r.errors.length?`${r.errors.length} замечаний по входным данным. Итог неполный.`:'Проверьте полноту состава изделия и согласуйте нормы перед выдачей цены.'}</div><div class="small" style="margin-top:15px">Расчёт обновляется при изменении объёмов, ставок и размера партии.</div></div>`}
function refreshSummary(){if($('summary'))$('summary').outerHTML=summary()}
function nextbar(){return `<div class="nextbar"><button onclick="go(${Math.max(0,page-1)})" ${page===0?'disabled':''}>← Назад</button><span class="small">Шаг ${page+1} из 5</span><button class="primary" onclick="go(${Math.min(4,page+1)})">${page===3?'Посмотреть результат':'Продолжить'} <span class="arrow">→</span></button></div>`}
function inlineVolumeHTML(line){return `<div class="inline-volume"><input class="inline-volume-input" id="inline-volume-${esc(line.id)}" type="number" min="0" step="any" value="${line.qty===null||line.qty===undefined?'':esc(line.qty)}" onchange="commitInlineVolume(event,'${esc(line.id)}')" aria-label="Объём ${esc(line.name)}"><span>${esc(MaterialCore.unitLabel(line.unit))}</span></div>`}
function commitInlineVolume(event,id){const line=state.lines.find(x=>x.id===id);if(!line)return;const raw=event.currentTarget.value.trim(),value=raw===''?null:Number(raw);if(value!==null&&(!Number.isFinite(value)||value<0)){event.currentTarget.value=line.qty??'';toast('Объём должен быть числом не меньше нуля');return;}const copy={...line,qty:value},errors=workspaceLineErrors(copy).filter(([key])=>key==='qty');if(errors.length){event.currentTarget.value=line.qty??'';toast(errors[0][1]);return;}line.qty=value;persist();render()}
function workRowsHTML(rows){const groups=Object.fromEntries(ProductionWorkCore.WORKSHOPS.map(name=>[name,[]]));rows.filter(x=>x.kind==='work').forEach((line,i)=>{const catalog=typeof CATALOG!=='undefined'?CATALOG.find(c=>c.id===line.catalogId):null;const workshop=ProductionWorkCore.WORKSHOPS.includes(line.workshop)?line.workshop:(catalog?ProductionWorkCore.classifyWorkshop(catalog).workshop:'Сборочный');groups[workshop].push({...line,workshop,productionOrder:Number.isInteger(line.productionOrder)?line.productionOrder:i});});return ProductionWorkCore.WORKSHOPS.map(workshop=>{const group=groups[workshop].sort((a,b)=>a.productionOrder-b.productionOrder);if(!group.length)return '';const batchCost=group.reduce((sum,l)=>sum+(Number.isFinite(l.amount)?l.amount:0),0),unitCost=state.qty>0?batchCost/state.qty:null;return '<tr class="workshop-row"><th colspan="6"><span>'+esc(workshop)+'</span><span class="workshop-cost">На изделие: '+money(unitCost)+' · На партию: '+money(batchCost)+'</span></th></tr>'+group.map(l=>'<tr class="work-line" data-work-id="'+esc(l.id)+'" data-workshop="'+esc(workshop)+'" ondragover="dragWorkOver(event)" ondrop="dropWorkLine(event,\''+esc(l.id)+'\')" ondragleave="dragWorkLeave(event)"><td class="rowname"><span class="drag-handle" draggable="true" ondragstart="dragWorkStart(event,\''+esc(l.id)+'\')" ondragend="dragWorkEnd(event)" aria-label="Перетащить позицию" title="Перетащить позицию">☰</span>'+esc(l.name)+'<span class="source">'+esc(l.group)+' · '+esc(MaterialCore.unitLabel(l.unit))+' '+(!l.confirmed?'· требует согласования':'')+'</span><span class="source">'+esc(l.source)+'</span></td><td>'+inlineVolumeHTML(l)+'</td><td>'+(l.scope==='unit'?'на изделие':'на партию')+'</td><td class="number">'+money(l.price)+'</td><td class="number work-cost-cell">'+money(l.amount)+(l.operationCost?'<span class="source">Подготовка: '+money(l.operationCost.setup)+' · до минимума: '+money(l.operationCost.minimumExtra)+'</span>':'')+'</td><td><button class="iconbtn" onclick="editLine(\''+esc(l.id)+'\')" aria-label="Изменить позицию">✎</button></td></tr>').join('');}).join('');}
let draggedWorkId=null;
function dragWorkStart(event,id){draggedWorkId=id;event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',id);event.currentTarget.closest('tr')?.classList.add('dragging');event.stopPropagation();}
function dragWorkOver(event){const row=event.currentTarget;if(!draggedWorkId||row.dataset.workId===draggedWorkId)return;const source=document.querySelector('[data-work-id="'+draggedWorkId+'"]');if(!source||source.dataset.workshop!==row.dataset.workshop)return;event.preventDefault();row.classList.add('drag-over');event.dataTransfer.dropEffect='move';}
function dragWorkLeave(event){event.currentTarget.classList.remove('drag-over');}
function dragWorkEnd(event){document.querySelectorAll('.work-line.dragging,.work-line.drag-over').forEach(row=>row.classList.remove('dragging','drag-over'));draggedWorkId=null;}
function ensureWorkWorkshop(line){if(!line)return '';if(ProductionWorkCore.WORKSHOPS.includes(line.workshop))return line.workshop;const catalog=typeof CATALOG!=='undefined'?CATALOG.find(c=>c.id===line.catalogId):null;line.workshop=catalog?ProductionWorkCore.classifyWorkshop(catalog).workshop:'Сборочный';return line.workshop;}
function dropWorkLine(event,targetId){event.preventDefault();event.currentTarget.classList.remove('drag-over');const id=draggedWorkId||event.dataTransfer.getData('text/plain');const line=state.lines.find(x=>x.id===id),target=state.lines.find(x=>x.id===targetId);if(!line||!target){draggedWorkId=null;return;}ensureWorkWorkshop(line);ensureWorkWorkshop(target);if(ProductionWorkCore.reorderWorkLine(state.lines,id,targetId)){persist();render();toast('Порядок сохранён');}else toast('Перемещение доступно только внутри своего цеха');draggedWorkId=null;}
function moveWorkLine(id,direction){const line=state.lines.find(x=>x.id===id);ensureWorkWorkshop(line);if(!ProductionWorkCore.moveWorkLine(state.lines,id,direction)){toast('Строка уже на границе своей группы');return;}persist();render();}
function render(){if(page!==20&&typeof window!=="undefined")window.GraphReact?.unmount();const r=CostEngine.calculate(state);$('catalogCount').textContent=dec(CATALOG.length)+' позиций · 11 разделов';$('nav').innerHTML=`${labels.map((l,i)=>`<button onclick="go(${i})" class="${page===i?'active':''}"><span class="num">0${i+1}</span>${l}</button>`).join('')}<button onclick="go(20)" class="${page===20?'active':''}">Технологическая схема</button><button onclick="go(19)" class="${page===19?'active':''}">Монтаж и спецификация</button><div class="navlabel">ПРОДАЖИ И ИЗДЕЛИЯ</div><button onclick="go(7)" class="${page===7?'active':''}"><span class="num">▦</span>База изделий</button><button onclick="go(8)" class="${page===8?'active':''}"><span class="num">↗</span>Коммерческое предложение</button><button onclick="go(9)" class="${page===9?'active':''}"><span class="num">▤</span>Реестр КП</button><div class="navlabel">ИНСТРУМЕНТЫ</div><button onclick="go(11)" class="${page===11?'active':''}"><span class="num">₽</span>Закупочные цены</button><button onclick="go(5)" class="${page===5?'active':''}"><span class="num">↗</span>Аналитика партии</button><button onclick="go(6)" class="${page===6?'active':''}"><span class="num">▤</span>Справочники</button><button onclick="go(18)" class="${page===18?'active':''}">▦ Реестр проектов</button>${typeof proNav==='function'?proNav():''}`;$('crumb').textContent=state.name;
 if(page===20){renderProcessGraph();return}if(page===19){renderInstallation();return}if(page===18){renderProjects();return}if(page===12){renderVariants();return}if(page===13){renderTarget();return}if(page===14){renderStockPlan();return}if(page===15){renderBreakdown();return}if(page===16){renderPriceSources();return}if(page===17){renderCloud();return}if(page===11){renderPurchases();return}if(page===7){renderLibrary();return}if(page===8){renderQuote();return}if(page===9){renderQuoteHistory();return}if(page===10){renderIssued();return}if(page===5){renderAnalytics();return}if(page===6){renderCatalog();return}
 if(page===4){renderResult();return}
 let body='';
 if(page===0)body=`<div class="card"><div class="cardhead"><h2><span class="section-num">01</span>Что будем считать?</h2><small>Карточка заказа</small></div><div class="field"><label>Тип расчёта</label><div class="choices">${['МАФ и мебель','Опалубка','Сервисные работы'].map((x,i)=>`<button class="choice ${state.type===x?'selected':''}" onclick="set('type','${x}');render()">${['◫','▧','⌁'][i]} &nbsp; ${x}<span>${['Изделия и конструкции','Изготовление и продажа','Работы и обслуживание'][i]}</span></button>`).join('')}</div></div>${field('Наименование изделия','name')}<div class="grid2">${field('Артикул изделия','code')}${field('Заказчик / объект','client')}</div><div class="grid2">${field('Размер партии, шт.','qty','number','Целое количество изделий. Общие затраты распределяются на партию.')}<div class="field"><label for="f-scope">Шаблон состава заказа</label><select id="f-scope" onchange="set('scope',this.value)">${['Изготовление','Изготовление и монтаж','Проектирование и изготовление','Сервис','Комплексный заказ'].map(x=>`<option ${state.scope===x?'selected':''}>${x}</option>`).join('')}</select></div></div>${field('Ограничения и состав для заказчика (без внутренних затрат)','clientNotes')}<div class="field"><label for="f-notes">Исходные данные, границы и допущения</label><textarea id="f-notes" rows="3" onchange="set('notes',this.value)" placeholder="Размеры, состав, покрытия, что входит в заказ…">${esc(state.notes)}</textarea></div></div><div class="note info">Начните с карточки, затем добавьте материалы и операции из ваших справочников. Цены и единицы перенесены из Excel; количества и закупочные кратности задаются для этого заказа.</div><button class="textbutton" onclick="loadDemo()">Посмотреть на учебном примере →</button>`;
 if(page===1||page===2){const kind=page===1?'material':'work',rows=r.rows.filter(x=>x.kind===kind);body=`<div class="card"><div class="cardhead"><h2>${kind==='material'?'Материалы и закупка':'Технологические операции'}</h2><button class="primary" onclick="picker('${kind}')">＋ Добавить ${kind==='material'?'материал':'операцию'}</button></div><p class="small">${kind==='material'?'Объёмы вводятся в единицах закупочной цены. Запас применяется один раз; закупка округляется до указанной кратности.':'Операции сгруппированы по цехам. Перетаскивайте строку за рукоятку слева; порядок сохраняется сразу.'}</p>${rows.length?`<div class="tablewrap"><table><thead><tr><th>Позиция / группа</th><th>Объём</th><th>База</th><th class="number">Ставка</th><th class="number">Затраты / цена услуги на партию</th><th></th></tr></thead><tbody>${kind==='work'?workRowsHTML(rows):rows.map(l=>`<tr><td class="rowname">${esc(l.name)}<span class="source">${esc(l.group)} · ${esc(MaterialCore.unitLabel(l.unit))} ${!l.confirmed?'· требует согласования':''}</span><span class="source">${esc(l.source)}</span></td><td>${inlineVolumeHTML(l)}<span class="source">запас ${dec(l.reserve)}% · кратность ${dec(l.pack)}</span></td><td>${l.scope==='unit'?'на изделие':'на партию'}</td><td class="number">${money(l.price)}</td><td class="number">${money(l.amount)}<span class="source">Закупка: ${dec(l.purchase)} ${esc(MaterialCore.unitLabel(l.unit))}</span></td><td>${materialActionsHTML(l.id)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><b>${kind==='material'?'Состав изделия начинается здесь':'Опишите процесс производства'}</b>Выберите позицию из справочника или создайте свою.<br><button style="margin-top:18px" onclick="picker('${kind}')">Открыть справочник →</button></div>`}<button class="textbutton" onclick="addManual('${kind}')">＋ Своя позиция</button></div>${kind==='work'?'<div class="card"><h2>Проектирование</h2><p class="small">Отдельная статья работ: ручной ввод человеко-часов и ставки ₽/ч.</p><button onclick="addDesign()">＋ Добавить проектирование</button></div>':''}${kind==='material'?'<div class="note">Кратность 1 — предложение до подтверждения.</div>':'<div class="note info">Ставка из справочника уже может включать оборудование и расходники.</div>'}`;}
if(page===3)body=`<div class="card"><div class="cardhead"><h2>Правила ценообразования</h2><small>Из описания расчётов</small></div><div class="grid2">${field('Накладные от работ, %','overhead','number')}${field('Транспорт от материалов, %','transport','number')}${field('Наценка, %','markup','number')}${field('НДС продажи, %','vat','number')}${field('Налог на прибыль, %','profitTax','number','Используется для показателя прибыли после налога.')}</div><div class="field"><label for="markupBase">Начислять наценку на</label><select id="markupBase" onchange="set('markupBase',this.value)">${Object.entries(CostEngine.MARKUP_BASES).map(([key,label])=>`<option value="${key}" ${(state.markupBase??'cost')===key?'selected':''}>${label}</option>`).join('')}</select><span class="hint">В работы входит проектирование. При выборе работ или работ и материалов накладные и транспорт включаются в себестоимость без наценки.</span></div><div class="note info">Закупочные цены учитываются с НДС. Входной НДС не вычитается из себестоимости. Это настройки вашей корпоративной калькуляции.</div><div class="divider"></div><h3>Как формируется цена</h3><div class="metricline"><span>Полная себестоимость</span><b>Материалы + работы + накладные + транспорт</b></div><div class="metricline"><span>Цена с НДС</span><b>(Себестоимость + выбранная база × наценка) × (1 + НДС)</b></div><p class="small">База наценки: ${esc(CostEngine.MARKUP_BASES[r.markupMode])} · ${money(r.markupBase)} на партию. Наценка: ${money(r.P)}. ${r.profitIncomplete?'Полная маржа неизвестна: не заданы затраты услуг.':'Фактическая маржа до НДС: '+dec(r.margin)+'%.'}</p></div><div class="card"><h2>Контроль перед выдачей</h2><div class="issue">Проверьте комплектность, нормы, запас, фасовку и актуальность закупочных цен. Подтверждение строки фиксирует проверку её объёма, запаса и кратности.</div><div class="issue">Замечания и согласование текущей версии доступны на шаге «Проверка и результат».</div></div>`;
 if(page===2)body=operationsCard()+body;
 if(page===0)body+=productImageCard();
 if(page===0&&typeof projectCard==='function')body=projectCard()+body;
 $('app').innerHTML=title('Расчёт изделия / '+String(page+1).padStart(2,'0'),labels[page],['От исходных данных — к прозрачной стоимости изделия.','Состав, объёмы и закупочная потребность.','От деталей — к последовательности работ.','Управляйте затратами и коммерческими параметрами.'][page])+steps()+`<div class="calculation-form">${body}${nextbar()}</div>`;if(page===0&&typeof projectOptions==='function')projectOptions();
}
function modal(t,h){$('modalTitle').textContent=t;$('modalBody').innerHTML=h;if(!$('modal').open)$('modal').showModal()}
function picker(kind){filterKind=kind;modal(kind==='work'?'Добавить операцию':'Добавить материал',`<div class="toolbar"><input id="search" placeholder="Поиск по названию, материалу или артикулу" oninput="searchCatalog()"><select id="cat" onchange="searchCatalog()"><option value="">Все разделы</option>${[...new Set(CATALOG.filter(x=>x.kind===kind).map(x=>x.sheet))].map(x=>`<option value="${esc(x)}">${esc(x.replaceAll('_',' '))}</option>`).join('')}</select></div><div class="small" id="found"></div><div class="catalog-results" id="results"></div>`);searchCatalog();$('search').focus()}
const catalogTextCache=new WeakMap();function catalogSearchText(c){if(!catalogTextCache.has(c))catalogTextCache.set(c,CatalogNormalization.search(c.name+' '+(c.sourceName||'')+' '+c.category+' '+c.sheet+' '+c.unit));return catalogTextCache.get(c)}
function searchCatalog(isFull=false){const matches=CatalogNormalization.matcher($(isFull?'fullSearch':'search')?.value||''),cat=$(isFull?'fullCat':'cat')?.value||'',list=CATALOG.filter(x=>(isFull||x.kind===filterKind)&&(!cat||x.sheet===cat)&&matches(catalogSearchText(x))),target=$(isFull?'fullResults':'results');$(isFull?'fullFound':'found').textContent=`Найдено ${dec(list.length)} · показано ${Math.min(list.length,150)}. ${list.length>150?'Уточните поиск для остальных позиций.':list.length===0?'Попробуйте название материала или другие размеры.':''}`;target.innerHTML=`<table><thead><tr><th>Наименование</th><th>Единица</th><th class="number">Цена</th><th>Дата</th><th></th></tr></thead><tbody>${list.slice(0,150).map(c=>`<tr><td class="rowname">${esc(c.name)}<span class="source">${esc(c.sheet)} · строка ${c.row} <button class="iconbtn" onclick="details('${esc(c.id)}')">Источник</button></span></td><td>${esc(MaterialCore.unitLabel(c.unit))}</td><td class="number ${c.price===null?'warning':''}">${money(c.price)}</td><td class="small">${esc(ReviewCore.dateLabel(c.date))}</td><td><button onclick="addCatalog('${esc(c.id)}')">＋ Добавить</button></td></tr>`).join('')}</tbody></table>`;}
let pendingNewLine=null;
function editableLine(id){return state.lines.find(x=>x.id===id)||(pendingNewLine?.id===id?pendingNewLine:null);}
function addCatalog(id){const c=CATALOG.find(x=>x.id===id);if(!c)return;const l=lineFrom(c);pendingNewLine=l;$('modal').close();editLine(l.id)}
function addManual(kind){filterKind=kind;const l=lineFrom();pendingNewLine=l;editLine(l.id)}
function details(id){const c=CATALOG.find(x=>x.id===id);modal('Источник ставки',`<p class="small">${esc(c.book)} · ${esc(c.sheet)} · ${esc(c.priceCell)}</p>${c.sourceName?`<p class="small">Исходное наименование: ${esc(c.sourceName)}</p>`:''}${purchaseUpdateInfo(c)}<pre>${esc(JSON.stringify(c.details,null,2))}</pre><p class="small">Цены справочника не проверялись по новым счетам. Исторический коэффициент запаса не применяется автоматически.</p><button onclick="picker('${c.kind}')">← В справочник</button>`)}
function editLine(id){const l=editableLine(id);if(!l)return;if(l.operation){operationDialog(id);return;}const inp=(label,k,type='number',hint='')=>`<div class="field"><label for="l-${k}">${label}</label><input id="l-${k}" type="${type}" value="${esc(['unit','physicalUnit'].includes(k)?MaterialCore.unitLabel(l[k]):l[k])}" ${type==='number'?'step="any" min="0"':''}>${hint?`<div class="hint">${hint}</div>`:''}</div>`;modal('Настройка позиции',`<form id="lineForm" class="modalform" novalidate onsubmit="commitLine(event,'${id}')"><div class="small">${esc(l.source)}</div>${pendingNewLine!==l&&typeof materialToolsHTML==='function'?materialToolsHTML(l):''}<button type="button" ${pendingNewLine===l?'hidden':''} class="textbutton" onclick="sourcePicker(state.lines.findIndex(x=>x.id==='${id}'))">Выбрать закупочную цену →</button><div class="divider"></div>${inp('Наименование','name','text')}${l.kind==='work'?`<div class="field"><label for="l-category">Статья работ</label><select id="l-category"><option value="">Производственные работы</option><option value="design" ${l.costCategory==='design'?'selected':''}>Проектирование</option></select></div>`:''}<div class="grid3">${inp(l.costCategory==='design'?'Трудоёмкость, '+MaterialCore.unitLabel(l.unit):'Объём','qty')}${inp('Единица ставки','unit','text')}${inp(l.costCategory==='design'?'Ставка, ₽ / '+MaterialCore.unitLabel(l.unit):'Цена за единицу, ₽','price','number','Пустое поле означает неизвестную цену.')}</div>${l.kind==='work'?`<details class="pricing-info" open><summary>Ценообразование</summary><p>${l.pricingMode==='individual'?'Стоимость за ед. указана индивидуально':'Базовая стоимость из источника: '+money(l.basePrice)}</p><p class="small">${esc(l.sourceFormula||'Формула и параметры будут доступны после актуализации источника.')}</p>${l.basePrice!==null&&l.basePrice!==undefined?`<button type="button" onclick="resetLineBase('${id}')">Сброс стоимости к базовым значениям</button>`:''}</details><div class="grid3">${inp('Физический объем','physicalQuantity','number')}${inp('Единица физического объема','physicalUnit','text')}${inp('Производительность за 1 н/ч','productivity','number')}</div>`:''}<div class="grid2"><div class="field"><label for="l-scope">Объём относится</label><select id="l-scope"><option value="unit" ${l.scope==='unit'?'selected':''}>К одному изделию</option><option value="batch" ${l.scope==='batch'?'selected':''}>Ко всей партии (разовая затрата)</option></select></div>${inp('Группа деталей / техпроцесс','group','text')}</div>${l.kind==='material'?`<div class="grid3">${inp('Запас, %','reserve')}${inp('Закупочная кратность','pack','number','В единицах ставки. Уточните фактическую фасовку.')}${inp('Масса чистой единицы, кг','mass','number','Без запаса и закупочных остатков.')}</div><div class="field"><label for="l-allocation">Отнесение закупки</label><select id="l-allocation"><option value="whole" ${l.allocation==='whole'?'selected':''}>Полная закупка на этот заказ</option><option value="share" ${l.allocation==='share'?'selected':''}>Только потребность изделия с запасом</option></select><div class="hint">При долевом учёте денежная закупка показывается отдельно. Доступный общий остаток между заказами пока не ведётся.</div></div><div class="grid2">${inp('Дата цены / источник актуальности','date','text')}<label class="checkrow"><input type="checkbox" id="l-deliveryIncluded" ${l.deliveryIncluded?'checked':''}>Доставка уже включена в цену — не начислять транспорт повторно</label></div>`:''}<label class="checkrow"><input type="checkbox" id="l-confirmed" ${l.confirmed?'checked':''}>Объём, единица, запас, способ распределения и закупочная кратность проверены для этого заказа</label><div class="mini-actions"><button type="submit" class="primary">Применить</button><button type="button" onclick="removeLine('${id}')">Удалить позицию</button></div><div id="lineError" class="warning" role="alert" tabindex="-1"></div></form>`)}
function workspaceLineErrors(line){
  const errors=[];
  if(!line.name.trim())errors.push(['name','Укажите наименование позиции.']);
  if(!line.unit.trim())errors.push(['unit','Укажите единицу ставки.']);
  if(!Number.isFinite(line.pack)||line.pack<=0)errors.push(['pack','Закупочная кратность должна быть больше нуля.']);
  for(const [key,label] of [['qty','Объём'],['price','Цена'],['reserve','Запас'],['mass','Масса']]){
    if(line[key]!==null&&(!Number.isFinite(line[key])||line[key]<0))errors.push([key,label+': введите число не меньше нуля.']);
  }
  if(line.materialType!==undefined&&!MaterialGroupingCore.validType(line.materialType))errors.push(['materialType','Выберите тип материала из списка.']);
  return errors;
}
function workspaceShowLineErrors(errors){
  const container=$('lineError');
  document.querySelectorAll('#lineForm .field-error').forEach(e=>e.remove());
  for(const key of ['name','unit','pack','qty','price','reserve','mass','materialType']){
    const input=$('l-'+key);input?.removeAttribute?.('aria-invalid');input?.removeAttribute?.('aria-describedby');
  }
  if(!errors.length){container.innerHTML='';return;}
  container.innerHTML='<strong>Проверьте поля:</strong><ul>'+errors.map(([key,message])=>'<li><button type="button" class="textbutton" onclick="document.getElementById(\'l-'+key+'\').focus()">'+esc(message)+'</button></li>').join('')+'</ul>';
  for(const [key,message] of errors){
    const input=$('l-'+key);for(let details=input?.closest?.('details');details;details=details.parentElement?.closest('details'))details.open=true;input?.setAttribute?.('aria-invalid','true');input?.setAttribute?.('aria-describedby','error-'+key);
    input?.insertAdjacentHTML?.('afterend','<p class="field-error" id="error-'+key+'">'+esc(message)+'</p>');
  }
  $('l-'+errors[0][0])?.focus();
}
function resetLineBase(id){const l=editableLine(id);if(!l||l.basePrice===null||l.basePrice===undefined){toast('Базовая стоимость отсутствует');return;}l.price=l.basePrice;l.unit=l.baseUnit||l.unit;l.pricingMode='calculated';l.sourceFormula=l.sourceFormula||'';l.unitChangeNotice=false;persist();editLine(id);toast('Стоимость сброшена к базовым значениям')}
function commitLine(e,id){e.preventDefault();const l=editableLine(id);if(!l)return false;const copy={...l};for(const k of ['name','unit','group','date','physicalUnit'])if($('l-'+k)){const value=$('l-'+k).value;copy[k]=['unit','physicalUnit'].includes(k)&&value===MaterialCore.unitLabel(l[k])?l[k]:value;}for(const k of ['qty','price','reserve','pack','mass','physicalQuantity','productivity'])if($('l-'+k)){const v=$('l-'+k).value;copy[k]=v===''?null:Number(v)}if(copy.kind==='material'&&$('l-materialType')){if($('l-materialType').value)copy.materialType=$('l-materialType').value;else delete copy.materialType;}if($('l-category'))copy.costCategory=$('l-category').value;copy.scope=$('l-scope').value;copy.confirmed=$('l-confirmed').checked;if($('l-allocation'))copy.allocation=$('l-allocation').value;if($('l-deliveryIncluded'))copy.deliveryIncluded=$('l-deliveryIncluded').checked;if($('l-workshop'))copy.workshop=$('l-workshop').value;const inputErrors=workspaceLineErrors(copy);if(copy.physicalQuantity!==null&&copy.physicalQuantity!==undefined&&(!Number.isFinite(copy.physicalQuantity)||copy.physicalQuantity<0))inputErrors.push(['physicalQuantity','Физический объем: введите число не меньше нуля.']);workspaceShowLineErrors(inputErrors);if(inputErrors.length)return false;if(copy.estimate&&(copy.price!==l.price||!MaterialCore.sameUnit(copy.unit,l.unit)||copy.mass!==l.mass)){copy.estimate=null;}if(copy.price!==l.price){copy.pricingMode='individual';}if(!MaterialCore.sameUnit(copy.unit,l.unit)){copy.unitChangeNotice=true;}else if(l.unitChangeNotice){copy.unitChangeNotice=false;}if(copy.workshop&&copy.workshop!==l.workshop)copy.productionOrder=null;if(pendingNewLine===l){state.lines.push(l);pendingNewLine=null;}if(copy.kind==='material'&&!copy.materialType)delete l.materialType;Object.assign(l,copy);persist();$('modal').close();render()}
function removeLine(id){if(pendingNewLine?.id===id){pendingNewLine=null;$('modal').close();return;}state.lines=state.lines.filter(l=>l.id!==id);persist();$('modal').close();render()}
function renderResult(){const r=CostEngine.calculate(state);$('app').innerHTML=title('Итоги расчёта',esc(state.name),'Внутренняя калькуляция и отдельное представление для заказчика.',r.partial?'Неполный расчёт':'Предварительная оценка')+steps()+`<div class="toolbar print-hide"><button class="${mode==='internal'?'primary':''}" onclick="mode='internal';renderResult()">Внутренний расчёт</button><button class="${mode==='client'?'primary':''}" onclick="mode='client';renderResult()">Для заказчика</button><span style="flex:1"></span>${mode==='client'?'<button class="primary" onclick="quoteFromCurrent()">Создать КП</button><button onclick="exportClient()">↓ Клиентский документ</button><button onclick="window.print()">Печать / PDF</button>':'<button class="primary" onclick="saveCalculation()">Сохранить версию</button><button onclick="quoteFromCurrent()">Создать КП</button><details class="action-menu"><summary>Экспорт и другие действия</summary><div class="action-menu-body"><button onclick="previewInternalPDF()">Внутренний отчёт / PDF</button><button onclick="exportInternalXLSX()">↓ Внутренний расчёт XLSX</button><button onclick="exportCSV()">↓ Детализация CSV</button><button onclick="reviewPriceRefresh()">Обновить цены</button><button onclick="rememberVariant()">＋ В сравнение</button><button onclick="updateVariant()">Обновить вариант сравнения</button></div></details>'}</div>`+(mode==='client'?clientDocument(r):`<div class="kpis"><div class="kpi"><div class="small">Себестоимость / шт.</div><div class="big">${money(r.costUnit)}</div><div class="small">${r.partial?'известная часть':'предварительно'}</div></div><div class="kpi featured"><div class="small">Цена / шт. с НДС</div><div class="big">${money(r.unit)}</div><div class="small">НДС ${dec(state.vat)}%</div></div><div class="kpi"><div class="small">Прибыль / шт. до НДС</div><div class="big">${money(r.P/state.qty)}</div><div class="small">${r.profitIncomplete?'Полная маржа неизвестна':'Маржа '+dec(r.margin)+'%'}</div></div><div class="kpi"><div class="small">Партия с НДС</div><div class="big">${money(r.total)}</div><div class="small">${dec(state.qty)} изделий</div></div></div><div class="layout"><section><div class="card"><div class="cardhead"><h2>Структура стоимости</h2><div class="row-actions"><button onclick="go(5)">Аналитика партии ↗</button><button onclick="go(15)">Разобрать затраты</button></div></div>${[['Материалы',r.M],['Производственные работы',r.W-r.D],['Проектирование',r.D],['Накладные',r.overhead],['Транспорт',r.transport],['Себестоимость',r.C],['База наценки · '+CostEngine.MARKUP_BASES[r.markupMode],r.markupBase],['Прибыль (наценка)',r.P],['Цена до НДС',r.net],['НДС продажи',r.tax],['Цена с НДС',r.total]].map(([n,v])=>`<div class="metricline"><span>${n}</span><b>${money(v)}</b></div>`).join('')}<div class="divider"></div><div class="metricline"><span>Денежная закупка материалов</span><b>${money(r.cash)}</b></div><div class="metricline"><span>Неотнесённая доля общей закупки</span><b>${money(r.cash-r.M)}</b></div><div class="metricline"><span>Масса установленных материалов / шт.</span><b>${r.massMissing||!state.lines.length?'неполная · ':''}${dec(r.mass)} кг</b></div><p class="small">Масса не включает неизвестные позиции и покрытия, если их масса не задана. Объёмы работ — в единицах ставки; трудоёмкость по ставкам за м² или п. м. отдельно не вычисляется.</p></div><div class="card"><h2>Закупочная ведомость</h2><div class="tablewrap"><table><thead><tr><th>Материал</th><th class="number">Потребность с запасом</th><th class="number">Закупка</th><th class="number">К оплате</th></tr></thead><tbody>${r.rows.filter(l=>l.kind==='material').map(l=>`<tr><td>${esc(l.name)}</td><td class="number">${dec(l.need)} ${esc(MaterialCore.unitLabel(l.unit))}</td><td class="number">${dec(l.purchase)} ${esc(MaterialCore.unitLabel(l.unit))}</td><td class="number">${money(l.purchase===null||l.price===null?null:l.purchase*l.price)}</td></tr>`).join('')}</tbody></table></div></div></section><section><div class="card"><h2>Границы расчёта</h2><p class="small">${esc(state.notes)||'Допущения и границы заказа пока не описаны.'}</p><button class="textbutton" onclick="go(0)">Уточнить исходные данные →</button></div></section></div>`)}
function clientDocument(r){return `<article class="document">${CJBrand.logoHTML()}<div class="dochead"><strong>Коммерческий расчёт</strong><span class="small">${new Date(state.updated).toLocaleDateString('ru-RU')}</span></div><h1>${esc(state.name)}</h1>${productImageHTML(state.productImage)}<p class="subtitle">${esc(state.code)}${state.client?' · '+esc(state.client):''}</p><div class="divider"></div><div class="metricline"><span>Предмет предложения</span><b>${esc(state.scope)}</b></div><div class="metricline"><span>Количество</span><b>${dec(state.qty)} шт.</b></div><span class="tag">${r.partial?'Неполный предварительный расчёт':'Предварительный расчёт'}</span><div class="tablewrap" style="margin-top:25px"><table><thead><tr><th>Наименование</th><th class="number">Количество</th><th class="number">Цена с НДС</th><th class="number">Сумма с НДС</th></tr></thead><tbody><tr><td>${esc(state.name)}</td><td class="number">${dec(state.qty)} шт.</td><td class="number">${money(r.unit)}</td><td class="number">${money(r.total)}</td></tr></tbody></table></div><div class="total"><span>${r.partial?'Известная часть':'Итого'} с НДС</span><strong>${money(r.total)}</strong></div><div class="metricline"><span>В том числе НДС ${dec(state.vat)}%</span><b>${money(r.tax)}</b></div><div class="note">${r.partial?'Расчёт неполный. Есть незаполненные объёмы или ставки; сумма отражает только рассчитанную часть. ':''}Цена предварительная и требует согласования комплектности, объёмов, норм и актуальности цен. Доставка и монтаж учитываются только в согласованном составе заказа.</div><p class="small" style="margin-top:23px">${esc(state.clientNotes||'')} Сумма партии рассчитана до округления цены за единицу. Предложение сформировано по текущему состоянию расчёта. Окончательная цена и сроки согласуются отдельно.</p></article>`}
function renderAnalytics(){const r=CostEngine.calculate(state),qs=[...new Set([1,5,10,25,50,100,state.qty])].sort((a,b)=>a-b),rs=qs.map(q=>CostEngine.calculate(state,q)),base=rs[0].unit,max=Math.max(...rs.map(x=>x.unit),1),points=rs.map((x,i)=>`${65+i*640/(rs.length-1)},${235-x.unit/max*180}`);$('app').innerHTML=title('Аналитика / Размер партии','Как тираж влияет на цену','Те же материалы и операции пересчитываются для каждого объёма.',r.partial?'Анализ известной части':'Предварительные сценарии')+`<div class="kpis"><div class="kpi"><div class="small">Единичное производство</div><div class="big">${money(base)}</div><div class="small">1 изделие с НДС</div></div><div class="kpi featured"><div class="small">Текущая партия · ${state.qty} шт.</div><div class="big">${money(r.unit)}</div><div class="small">за изделие с НДС</div></div><div class="kpi"><div class="small">Изменение к 1 изделию</div><div class="big">${base?dec((1-r.unit/base)*100):'—'}%</div><div class="small">за счёт закупки и разовых затрат</div></div><div class="kpi"><div class="small">Подготовка на всю партию</div><div class="big">${money(r.rows.filter(l=>l.kind==='work').reduce((t,l)=>t+(l.operationCost?l.operationCost.setup:(l.scope==='batch'?l.amount||0:0)),0))}</div><div class="small">без накладных и наценки</div></div></div><div class="card"><div class="cardhead"><h2>Цена одного изделия с НДС</h2><div><label for="analyticsQty">Размер вашей партии</label><input style="width:110px" id="analyticsQty" type="number" min="1" step="1" value="${state.qty}" onchange="if(Number.isInteger(+this.value)&&+this.value>0){set('qty',+this.value)}else{toast('Нужно целое положительное количество')}"></div></div><svg class="chart" viewBox="0 0 770 290" role="img" aria-label="Цена одного изделия по размеру партии">${[0,.5,1].map(f=>`<line x1="65" x2="730" y1="${235-f*180}" y2="${235-f*180}" stroke="#e5eadd"/><text x="0" y="${239-f*180}">${dec(max*f)}</text>`).join('')}<polygon points="65,235 ${points.join(' ')} 705,235" fill="#e8f0e0"/><polyline points="${points.join(' ')}" fill="none" stroke="#466b45" stroke-width="3"/>${rs.map((x,i)=>`<circle cx="${65+i*640/(rs.length-1)}" cy="${235-x.unit/max*180}" r="5" fill="#466b45"><title>${x.q} шт.: ${money(x.unit)}</title></circle><text x="${65+i*640/(rs.length-1)}" y="265" text-anchor="middle">${x.q} шт.</text>`).join('')}</svg></div><div class="card"><h2>Сравнение сценариев</h2><div class="tablewrap"><table><thead><tr><th>Партия</th><th class="number">Закупка материалов</th><th class="number">Себестоимость / шт.</th><th class="number">Цена / шт. с НДС</th><th class="number">Вся партия</th><th></th></tr></thead><tbody>${rs.map(x=>`<tr ${x.q===state.qty?'style="background:#f0f5ea"':''}><td><b>${x.q} шт.</b></td><td class="number">${money(x.cash)}</td><td class="number">${money(x.costUnit)}</td><td class="number">${money(x.unit)}</td><td class="number">${money(x.total)}</td><td><button class="iconbtn" onclick="set('qty',${x.q})">Выбрать</button></td></tr>`).join('')}</tbody></table></div></div><div class="note info">Скидки поставщиков и рост производительности не предполагаются автоматически. Изменение цены возникает из округления закупки и распределения позиций «на партию». Сценарии используют одинаковый состав и нормы.</div>`}
function renderCatalog(){$('app').innerHTML=title('База производства','Ваши справочники',`${dec(CATALOG.length)} позиций из предоставленных книг. Цена, единица и исходная строка сохраняются.`,'Цены из справочников и заказов')+`<div class="toolbar"><button class="primary" onclick="go(11)">Закупочные цены 2026 →</button><button onclick="reviewPriceRefresh()">Обновить цены текущего расчёта</button></div><div class="note info">Добавлен прайс СтальГрад от 07.10.2026: ${METAL_IMPORT.count} новых позиций. Розница с НДС; опт сохранён справочно в карточке источника. ${METAL_IMPORT.review} позиций требуют проверки базы цены — числовая ставка для них не применяется.</div><div class="card"><div class="toolbar"><input id="fullSearch" aria-label="Поиск по справочнику" placeholder="Например: лиственница, лист нержавеющий, саморез…" oninput="searchCatalog(true)"><select id="fullCat" aria-label="Раздел справочника" onchange="searchCatalog(true)"><option value="">Все разделы</option>${[...new Set(CATALOG.map(x=>x.sheet))].map(x=>`<option value="${esc(x)}">${esc(x.replaceAll('_',' '))}</option>`).join('')}</select></div><div class="small" id="fullFound"></div><div class="tablewrap" id="fullResults"></div></div><div class="mini-actions"><button onclick="showSources()">Источники и методика</button><button onclick="showArchive()">Открыть архив старой сметы</button></div>`;searchCatalog(true)}
function showSources(){modal('Источники и правила расчёта',`<p>Дополнено прайсом «СтальГрад» от 07.10.2026. Для новых позиций сохранены исходная строка, единицы и розничная цена с НДС. Неоднозначные ставки оставлены пустыми. Оптовые цены не применяются автоматически.</p><p>Перенесено <b>${dec(CATALOG.length)} позиций</b> из 11 разделов. У ${CATALOG.filter(x=>x.price===null).length} позиций нет корректной числовой цены; такие ставки остаются неизвестными.</p><table><tbody><tr><td>Данные.xlsx</td><td>Основной справочник: материалы, работы, покрытия и крепёж.</td></tr><tr><td>Сметный калькулятор СК-V-3.06.xlsx</td><td>Историческая структура, архив сметы и дополнительный раздел брусчатки. Дубли основного справочника не подменяют его.</td></tr><tr><td>Скилл расчёта изделий.md</td><td>Описание корпоративной логики: накладные 7% работ, транспорт 6% материалов, наценка 40%, НДС продажи 22%. Настройки редактируются в расчёте.</td></tr></tbody></table><div class="divider"></div><p class="small">Дополнительно подключён отчёт «Закупки_цены_и_зависимость_от_объема.md»: 4287 строк закупочной номенклатуры, рубли подтверждены пользователем. Последние исторические ставки применяются только для сопоставленных позиций; весь источник доступен в разделе «Закупочные цены». Исходные файлы не изменялись. Нормы и коэффициенты запаса не переносятся как согласованные значения заказа. Ставки работ используются в исходной единице: повторный пересчёт производительности не выполняется. Ошибки #NAME? и #REF! исторической книги не заменяются нулевыми ценами.</p><div class="note">Рабочий черновик хранится в браузере. Сохранённые изделия, КП, варианты, остатки и источники синхронизируются с сервером при подключении. Состояние синхронизации и резервные копии доступны в разделе «Сервер и копии». Раскрой и автоматическое списание склада не выполняются.</div><div class="mini-actions"><button onclick="showArchive()">Посмотреть историческую смету</button></div>`)}
function showArchive(){modal('Архив исходного калькулятора',`<p class="small">Содержимое исторических листов для сверки. Ошибки оригинала сохранены как текст; это не действующий расчёт.</p><div class="toolbar"><select id="archiveSheet" onchange="archiveTable()">${Object.keys(ARCHIVE).map(s=>`<option>${esc(s)}</option>`).join('')}</select><input id="archiveQuery" placeholder="Поиск по строкам" oninput="archiveTable()"></div><div class="catalog-results" id="archiveRows"></div>`);archiveTable()}
function archiveTable(){const s=$('archiveSheet').value,q=$('archiveQuery').value.toLowerCase(),rows=ARCHIVE[s].rows.filter(r=>JSON.stringify(r.cells).toLowerCase().includes(q));$('archiveRows').innerHTML=rows.slice(0,200).map(r=>`<div class="archive-row"><b>Строка ${r.row}</b><pre>${esc(Object.entries(r.cells).map(([k,v])=>k+': '+v).join('\n'))}</pre></div>`).join('')+`<p class="small">Найдено ${rows.length} строк; показано до 200.</p>`}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),500)}
function saveFile(){persist();download('raschet-'+(state.code.replace(/[^a-zA-Zа-яА-Я0-9-]/g,'')||'izdelie')+'.json',JSON.stringify(state,null,2),'application/json')}
async function importFile(e){const file=e.target.files[0];if(!file)return;try{if(file.size>8e6)throw Error();const s=JSON.parse(await file.text());if(!validState(s))throw Error();state=s;persist();page=0;render();toast('Расчёт открыт')}catch{toast('Не удалось открыть: требуется JSON проекта «Изделие»')}e.target.value=''}
function exportClient(){const r=CostEngine.calculate(state);const html='<!doctype html><html lang="ru"><meta charset="utf-8"><title>Коммерческий расчёт</title><style>body{font:14px Arial;color:#262626;max-width:850px;margin:50px auto;padding:20px}table{width:100%;border-collapse:collapse;margin:25px 0}td,th{padding:13px;border-bottom:1px solid #BFBFBF;text-align:left}.number{text-align:right}.metricline,.total,.dochead{display:flex;justify-content:space-between;margin:18px 0}.total{font-size:22px;border-top:2px solid;padding-top:20px}.small,.subtitle{color:#595959;font-size:12px}.note{padding:20px;background:#f5f2e8;margin-top:25px}.tag{color:#966f39}</style>'+clientDocument(r)+'</html>';download('predlozhenie.html',html,'text/html;charset=utf-8');toast('Отдельный документ без внутренних ставок и себестоимости')}
function exportCSV(){const r=CostEngine.calculate(state),safe=v=>{let t=String(v??'');if(/^[=+@-]/.test(t))t="'"+t;return '"'+t.replace(/"/g,'""')+'"'},rows=[['Позиция','Тип','Группа','База','Единица','Объем','Запас %','Кратность','Цена','Потребность партии','Закупка','На заказ','Источник'],...r.rows.map(l=>[l.name,l.kind,l.group,l.scope,MaterialCore.unitLabel(l.unit),l.qty,l.reserve,l.pack,l.price,l.need,l.purchase,l.amount,l.source])];download('vnutrennyaya-kalkulyatsiya.csv','\uFEFF'+rows.map(row=>row.map(safe).join(';')).join('\r\n'),'text/csv;charset=utf-8')}
render();


function materialActionsHTML(id){return `<span class="material-actions"><button onclick="editLine('${esc(id)}')" aria-label="Изменить позицию">Изменить</button><button type="button" class="iconbtn" onclick="removeLine('${esc(id)}')" aria-label="Удалить материал" title="Удалить материал"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 6h18M9 6V4h6v2M5 6l1 14h12l1-14M10 10v6M14 10v6"/></svg></button></span>`;}
